   CONSTRAINT PK_WARENBEWERTUNG_ABSCHLUSS PRIMARY KEY (wup_id, nb_id, mandant_id, system_id, buchungskreis_id, dat_aenderung, art_id, version_id) NOT ENFORCED
)  COMMENT = 'WWC - Tabelle für die Warenbewertung nach zwei Versionen, artikelgenau und pauschal.';
